-- READ-ONLY 2013 source-paired RH candidates with exact local +/-300s target brackets.
SELECT o.dateTime target_time,o.outHumidity old_rh,w.outHumidity wh_rh,o.outTemp old_temp,w.outTemp wh_temp,o.usUnits old_units,w.usUnits wh_units,o.`interval` old_interval,w.`interval` wh_interval,r.outHumidity target_rh,r.outTemp target_temp,rp.outHumidity prev_rh,rn.outHumidity next_rh,rp.outTemp prev_temp,rn.outTemp next_temp,eo.outHumidity euold_rh,e.outHumidity eu_rh,g.outHumidity gw_rh,l.relative_humidity_pct luhamet_rh,(SELECT COUNT(*) FROM loucka_reconstruction.reconstruction_changes c WHERE c.target_time=o.dateTime AND c.variable='outHumidity') rh_history_events FROM old_weewx.archive o JOIN weewx_WH1080.archive w ON w.dateTime=o.dateTime JOIN loucka_reconstruction.archive r ON r.dateTime=o.dateTime JOIN loucka_reconstruction.archive rp ON rp.dateTime=o.dateTime-300 JOIN loucka_reconstruction.archive rn ON rn.dateTime=o.dateTime+300 LEFT JOIN `pocasi-loucka.eu_old`.archive eo ON eo.dateTime=o.dateTime LEFT JOIN `pocasi-loucka.eu`.archive e ON e.dateTime=o.dateTime LEFT JOIN `pocasi-loucka.eu_GW1000`.archive g ON g.dateTime=o.dateTime LEFT JOIN loucka_reconstruction.reference_observations l ON l.station_id='luhamet_sehradice' AND l.observed_at_utc=o.dateTime WHERE o.dateTime>=1356998400 AND o.dateTime<1388534400 AND o.outHumidity IS NOT NULL AND w.outHumidity IS NOT NULL AND o.outHumidity=w.outHumidity AND r.outHumidity IS NULL AND rp.outHumidity IS NOT NULL AND rn.outHumidity IS NOT NULL AND NOT EXISTS(SELECT 1 FROM loucka_reconstruction.reconstruction_changes c WHERE c.target_time=o.dateTime AND c.variable='outHumidity') ORDER BY o.dateTime;
